function options(values,selected=''){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function openTransactionForm(id){const old=id?state.transactions.find(t=>t.id===id):null;let ty=old?.type||'withdrawal',photo=old?.receiptDataUrl||'';openModal(old?'تعديل المعاملة':'إضافة معاملة جديدة',`<form id="transactionForm"><div class="pillbox"><button type="button" class="${ty==='withdrawal'?'active debit':''}" data-transaction-mode="withdrawal">↗ سحب</button><button type="button" class="${ty==='deposit'?'active':''}" data-transaction-mode="deposit">↙ إيداع</button></div><input type="hidden" name="type" id="txType" value="${ty}"/>
<div class="field-grid"><div class="field"><label>المبلغ بالجنيه *</label><input name="amount" type="number" min="0.01" max="999999999999" step="0.01" required inputmode="decimal" placeholder="0.00" value="${old?.amount??''}"></div><div class="field"><label>التاريخ *</label><input name="date" type="date" required value="${old?.date||localDate()}"></div></div>
<div class="field"><label>الوصف *</label><input name="note" required maxlength="120" placeholder="مثلاً: مشتريات السوبر ماركت" value="${esc(old?.note||'')}"></div><div class="field"><label>التصنيف</label><select name="category" id="txCategory">${options(old?.type==='deposit'?['إيداع','راتب','تحويل وارد']:['مشتريات',...categories()],old?.category||'مشتريات')}</select></div>
<div class="field"><label>مصدر العملية</label><select name="source">${options(SOURCES,old?.source||'نقدي')}</select></div><div class="field"><label>نص رسالة SMS (اختياري)</label><textarea name="originalMessage" maxlength="10000" placeholder="الصق الرسالة الأصلية للاحتفاظ بيها داخل المعاملة">${esc(old?.originalMessage||'')}</textarea></div>
<div class="field"><label>إرفاق صورة أصلية أو إيصال (اختياري)</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/heic"><span class="field-hint">يفضل صورة بدون بيانات بطاقتك الكاملة. الصورة هتتحفظ محليًا.</span></div>
<div class="checks"><input type="checkbox" name="excluded" id="excludeTx" ${old?.excluded?'checked':''}><label for="excludeTx">تحويل بين حساباتي / تجاهل من إجمالي السحب والإيداع</label></div>
<div class="buttons"><button class="btn block" type="submit">${old?'حفظ التعديل':'حفظ المعاملة'}</button>${old?`<button type="button" class="btn danger block" id="deleteTransaction">حذف المعاملة</button>`:''}</div></form>`,()=>{const form=$('#transactionForm');form.addEventListener('click',e=>{let el=e.target.closest('[data-transaction-mode]');if(!el)return;const v=el.dataset.transactionMode;$('#txType').value=v;form.querySelectorAll('[data-transaction-mode]').forEach(b=>b.classList.toggle('active',b.dataset.transactionMode===v));form.querySelectorAll('[data-transaction-mode]').forEach(b=>b.classList.toggle('debit',b.dataset.transactionMode===v&&v==='withdrawal'));$('#txCategory').innerHTML=options(v==='deposit'?['إيداع','راتب','تحويل وارد','أخرى']:categories(),v==='deposit'?'إيداع':'مشتريات')});form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),amount=cleanMoney(f.get('amount')),date=String(f.get('date'));if(!amount||!validDate(date)){toast('اكتب مبلغ وتاريخ صحيحين');return}const file=form.elements.image.files[0];if(file){try{photo=await compressPhoto(file)}catch(err){toast(err.message);return}}const data={id:old?.id||uuid(),type:f.get('type'),amount,date,note:String(f.get('note')).slice(0,120),category:String(f.get('category')),source:String(f.get('source')),originalMessage:String(f.get('originalMessage')||''),receiptDataUrl:photo,excluded:form.elements.excluded.checked,sender:old?.sender||'',fingerprint:old?.fingerprint||'',linkedInstallment:old?.linkedInstallment||'',createdAt:old?.createdAt||new Date().toISOString()};if(old){Object.assign(old,data)}else state.transactions.push(data);if(!await persist())return;closeModal();viewMonth=date.slice(0,7);render();toast(old?'تم تعديل المعاملة':'تمت إضافة المعاملة')});$('#deleteTransaction')?.addEventListener('click',async()=>{if(!confirm('تحذف المعاملة نهائيًا؟'))return;state.transactions=state.transactions.filter(t=>t.id!==old.id);for(const inst of state.installments)inst.payments=(inst.payments||[]).filter(p=>p.txId!==old.id);await persist();closeModal();render();toast('تم حذف المعاملة')})})}
async function compressPhoto(file){if(file.size>15*1024*1024)throw Error('الصورة كبيرة جدًا (الحد 15 ميجابايت)');if(!/^image\/(png|jpeg|webp|heic|heif)$/i.test(file.type)&&!/(png|jpg|jpeg|webp|heic)$/i.test(file.name))throw Error('اختار صورة PNG أو JPG أو WEBP');const blob=await new Promise((resolve,reject)=>{const fr=new FileReader;fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(Error('تعذر قراءة الصورة'));fr.readAsDataURL(file)});return new Promise((resolve,reject)=>{const img=new Image;img.onload=()=>{const ratio=Math.min(1,1200/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.floor(img.width*ratio));c.height=Math.max(1,Math.floor(img.height*ratio));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const result=c.toDataURL('image/jpeg',.7);if(result.length>1700000)reject(Error('حجم الصورة بعد الضغط كبير؛ جرّب صورة أصغر'));else resolve(result)};img.onerror=()=>reject(Error('تعذر فتح الصورة. جرّب JPG أو PNG بدل HEIC'));img.src=blob})}
function openDetails(id){const t=state.transactions.find(x=>x.id===id);if(!t)return;openModal('تفاصيل المعاملة',`<div class="row between"><span class="tag ${t.type==='deposit'?'green':'red'}">${t.type==='deposit'?'↙ إيداع':'↗ سحب'}</span><span class="small muted">${esc(displayDate(t.date))}</span></div><div class="large-amount ${t.type==='deposit'?'green':'red'}">${t.type==='deposit'?'+':'−'}${money(t.amount)} ج.م</div><div class="metric"><span class="muted small">الوصف</span><strong>${esc(t.note||'—')}</strong></div><div class="metric"><span class="muted small">التصنيف</span><strong>${esc(t.category||'أخرى')}</strong></div><div class="metric"><span class="muted small">المصدر</span><strong>${esc(t.source||'—')}</strong></div>${t.excluded?'<p class="alert">هذه العملية مستبعدة من الحسابات (تحويل بين حساباتك).</p>':''}${t.originalMessage?`<div class="section"><strong>🧾 نص الرسالة المحفوظ</strong><div class="receipt" style="margin-top:10px" dir="auto">${esc(t.originalMessage)}</div><div class="buttons" style="margin-top:10px"><button class="btn secondary small" id="receiptExport">حفظ إيصال بصورة PNG</button></div></div>`:''}${t.receiptDataUrl?`<div class="section"><strong>الصورة الأصلية المرفقة</strong><img class="receipt-image" src="${t.receiptDataUrl}" alt="صورة مرفقة للمعاملة"></div>`:''}<div class="buttons" style="margin-top:17px"><button class="btn block" id="editTx">تعديل المعاملة</button></div>`,()=>{$('#editTx').addEventListener('click',()=>openTransactionForm(t.id));$('#receiptExport')?.addEventListener('click',()=>exportReceipt(t))})}
function exportReceipt(t){if(!t.originalMessage)return;const c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=1000;ctx.font='27px Tahoma, Arial';const maxWidth=890,words=String(t.originalMessage).split(/\s+/);let lines=[],line='';for(let word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines=lines.slice(0,85);c.height=Math.max(460,340+lines.length*45);ctx.fillStyle='#0f1721';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='right';ctx.direction='rtl';ctx.fillStyle='#61dcbc';ctx.font='bold 47px Tahoma,Arial';ctx.fillText('حساباتي | إثبات المعاملة',940,90);ctx.fillStyle='#fff';ctx.font='bold 33px Tahoma,Arial';ctx.fillText(`${money(t.amount)} جنيه — ${t.type==='deposit'?'إيداع':'سحب'}`,940,160);ctx.font='25px Tahoma,Arial';ctx.fillStyle='#aac3d2';ctx.fillText(`${t.date} · ${t.source||''}`,940,205);ctx.strokeStyle='#334a5c';ctx.strokeRect(35,235,930,lines.length*45+35);ctx.fillStyle='#fff';ctx.font='27px Tahoma,Arial';lines.forEach((l,i)=>ctx.fillText(l,938,285+i*45));ctx.fillStyle='#9cb4c2';ctx.font='19px Tahoma,Arial';ctx.fillText('إيصال مولّد من نص الرسالة — ليس لقطة شاشة أصلية من Messages',940,c.height-34);c.toBlob(blob=>{if(!blob)return toast('تعذر إنشاء الصورة');downloadBlob(blob,'receipt-'+t.date+'.png')},'image/png')}
function checksum(s){let n=2166136261;for(let i=0;i<s.length;i++){n^=s.charCodeAt(i);n=Math.imul(n,16777619)}return (n>>>0).toString(16)}
function standardNum(s){return String(s).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c)))}
function smsMerchant(text){
 const cleaned=standardNum(String(text||'')).replace(/\s+/g,' ').trim();
 const patterns=[
  /(?:\bat\s+|\bmerchant\s*[:\-]\s*|\bpayee\s*[:\-]\s*)([\p{L}\p{N}&.'\- ]{2,75}?)(?=\s+(?:on\s+\d|using\b|via\b|card\b|ref(?:erence)?\b|available\b|balance\b|EGP\b|LE\b|ending\b)|[,;]|$)/iu,
  /(?:لدى|عند|لصالح|التاجر\s*[:\-]|من\s+(?!حساب|بطاق|رصيد|البنك)|في\s+(?!حساب|البنك))\s*([\p{L}\p{N}&.'\- ]{2,75}?)(?=\s+(?:بتاريخ|الرصيد|رصيد|المتاح|رقم|جنيه|من\s+حساب|باستخدام|بتوقيت|EGP\b)|[,؛.;]|$)/iu
 ];
 for(const rx of patterns){
  const m=cleaned.match(rx);if(!m)continue;
  let name=m[1].trim().replace(/[.،;:]+$/,'').trim();
  if(name.length>1&&!/^(?:your|account|bank|card|حسابك|حساب|البنك|بطاقة|الرصيد)$/iu.test(name))return name.slice(0,70);
 }
 return '';
}
function parseSMS(r){let body=String(r.body||r.message||r.text||'').trim().slice(0,10000),sender=String(r.sender||r.from||'').slice(0,100),date=String(r.date||localDate()).slice(0,10);if(!validDate(date))date=localDate();const text=standardNum(body),low=text.toLowerCase();let type=null,scoreD=0,scoreW=0;if(/\b(credited|received|deposit(?:ed)?|incoming|added to account)\b|(?:تم|قد)\s*(?:إيداع|ايداع|استلام)|(?:استلام|إيداع|ايداع|وارد)|تحويل\s+وارد|اضاف[ةه]\s+مبلغ/.test(low))scoreD+=3;if(/\b(debited|withdrawn|withdrawal|purchase|purchased|spent|paid|payment|pos transaction|transaction at|cash withdrawal)\b|(?:تم|قد)\s*(?:خصم|سحب|دفع)|(?:خصم|سحب|شراء|مشتريات|مدفوع|دفع|تحويل\s+صادر)/.test(low))scoreW+=3;if(/\b(?:sent to|transferred to)\b|تحويل\s+(?:الى|إلى)/.test(low))scoreW+=2;if(/\b(?:from|by)\s+(?:instapay|vodafone cash)\b/.test(low))scoreD+=1;if(/\b(?:credit card|بطاق[ةه]\s+ائتمان)/.test(low))scoreW+=1;
if(/\b(otp|one.time.pass|verification code|security code|pin code)\b|(?:رمز|كود)\s*(?:التحقق|التاكيد|التأكيد)|كلمة\s+المرور\s+المؤقت/.test(low)&&scoreD===0&&scoreW===0)return{body,sender,date,type:null,amount:0,ignored:true,reason:'رسالة تحقق لا تحتوي معاملة'};
if(scoreD>scoreW)type='deposit';else if(scoreW>scoreD)type='withdrawal';
const matches=[];const rx1=/((?:\d[\d,\. ]{0,19}))\s*(?:egp\b|جنيه|ج\s*\.?\s*م\.?\b|l\.e\.?\b)/gi,rx2=/(?:egp\b|جنيه|ج\s*\.?\s*م\.?\b|l\.e\.?\b)\s*([\d][\d,\. ]{0,19})/gi;for(let rx of [rx1,rx2]){for(const match of text.matchAll(rx)){const amt=cleanMoney(match[1]);if(amt>0&&amt<1e12){let preceding=low.slice(Math.max(0,match.index-40),match.index);let penalty=/balance|الرصيد|المتاح|available|current bal/.test(preceding)?100:0;matches.push({amount:amt,index:match.index,penalty})}}}matches.sort((a,b)=>a.penalty-b.penalty||a.index-b.index);let amount=matches[0]?.amount||0;
let category=type==='deposit'?'إيداع':'أخرى';if(type==='withdrawal'){if(/carrefour|supermarket|hyper|سوبر|ماركت|بقال[ةه]/.test(low))category='مستلزمات بيت';else if(/netflix|spotify|youtube premium|شاهد|اشتراك|subscription/.test(low))category='اشتراكات';else if(/electricity|كهرب/.test(low))category='كهرباء';else if(/water bill|مياه/.test(low))category='مياه';else if(/vodafone|orange|etisalat|recharge|شحن/.test(low))category='مصاريف شحن';else if(/amazon|noon|jumia|shopping|store|shop|محل|مشتريات/.test(low))category='مشتريات';else if(/uber|careem|transport|تاكسي/.test(low))category='مواصلات';else if(/restaurant|cafe|مطعم|كافيه/.test(low))category='مطاعم'}
const merchant=smsMerchant(body);const fp=checksum(date+'|'+sender.toLowerCase()+'|'+body.replace(/\s+/g,' ').toLowerCase());let ignored=!body;return{body,sender,date,type,amount,merchant,category,source:r.source||sender||'SMS',fingerprint:fp,ignored,reason:ignored?'رسالة فارغة':(!type?'نوع العملية يحتاج مراجعة':(!amount?'المبلغ يحتاج مراجعة':''))}}
function csvParse(src){const out=[];let row=[],cur='',quote=false;for(let i=0;i<src.length;i++){let ch=src[i];if(quote){if(ch==='"'&&src[i+1]==='"'){cur+='"';i++}else if(ch==='"')quote=false;else cur+=ch}else{if(ch==='"')quote=true;else if(ch===','){row.push(cur);cur=''}else if(ch==='\n'){row.push(cur.replace(/\r$/,''));out.push(row);row=[];cur=''}else cur+=ch}}row.push(cur);if(row.some(x=>x))out.push(row);let heads=(out.shift()||[]).map(x=>x.trim().toLowerCase());return out.map(r=>{let x={};heads.forEach((h,i)=>x[h]=r[i]||'');return{sender:x.sender||x.from||x['المرسل']||'',date:x.date||x['التاريخ']||localDate(),body:x.body||x.message||x.text||x['الرسالة']||'',source:x.source||x['المصدر']||''}})}
function readMessageData(text,fileName=''){const trimmed=text.trim();if(!trimmed)throw Error('الملف فارغ');if(/\.csv$/i.test(fileName))return csvParse(trimmed);if(trimmed[0]==='['||trimmed[0]==='{'){try{const v=JSON.parse(trimmed);return(Array.isArray(v)?v:Array.isArray(v.messages)?v.messages:[v]).map(t=>typeof t==='string'?{body:t}:t)}catch(e){if(/\.json$/i.test(fileName))throw Error('صيغة JSON غير صحيحة')}}return trimmed.split(/\n-{3,}\n/).filter(Boolean).map(x=>({body:x.trim()}))}
function openSmsModal(){smsPreview=[];openModal('استيراد رسائل SMS',`<p class="footnote">الصق نص الرسالة المالية هنا أو استورد ملف من Apple Shortcuts. مش بنقرأ صندوق رسائل الآيفون مباشرة.</p><div class="field-grid"><div class="field"><label>مرسل الرسالة</label><input id="smsSender" placeholder="مثلاً CIB"></div><div class="field"><label>التاريخ</label><input id="smsDate" type="date" value="${localDate()}"></div></div><div class="field"><label>نص رسالة SMS</label><textarea id="smsBody" placeholder="مثال: Your card has been debited with EGP 850.00 at Carrefour..."></textarea></div><div class="buttons"><button class="btn" type="button" id="previewSms">تحليل الرسالة</button><button class="btn secondary" type="button" id="smsLoadFile">📁 استيراد ملف TXT / CSV / JSON</button></div><div id="smsResults"></div>`,()=>{$('#previewSms').addEventListener('click',()=>{const body=$('#smsBody').value.trim();if(!body)return toast('الصق نص الرسالة الأول');showSmsPreview([{body,sender:$('#smsSender').value,date:$('#smsDate').value}])});$('#smsLoadFile').addEventListener('click',()=>{$('#hiddenSmsFile').value='';$('#hiddenSmsFile').click()})})}
function showSmsPreview(records){if(!$('#smsResults'))openSmsModal();smsPreview=records.slice(0,200).map(parseSMS);const dup=new Set(state.transactions.map(x=>x.fingerprint).filter(Boolean));$('#smsResults').innerHTML=`<div class="section"><div class="section-heading"><h2>مراجعة قبل التسجيل (${smsPreview.length})</h2></div><div class="alert good">راجع نوع العملية والمبلغ قبل الحفظ. الرسائل المكررة هتتجاهل تلقائيًا.</div><div class="sms-preview">${smsPreview.map((p,idx)=>`<div class="item" data-sms-row="${idx}"><div class="row between"><strong>رسالة ${idx+1}</strong>${dup.has(p.fingerprint)?'<span class="tag yellow">مكررة</span>':p.ignored?'<span class="tag yellow">مستبعدة</span>':(!p.type||!p.amount)?'<span class="tag yellow">مراجعة ضرورية</span>':'<span class="tag green">تم التحليل</span>'}</div><div class="preview-raw">${esc(p.body.slice(0,300))}</div><div class="field-grid"><div class="field"><label>النوع</label><select data-sms-type="${idx}"><option value="">غير محدد</option><option value="withdrawal" ${p.type==='withdrawal'?'selected':''}>سحب</option><option value="deposit" ${p.type==='deposit'?'selected':''}>إيداع</option><option value="ignore">تجاهل</option></select></div><div class="field"><label>المبلغ</label><input data-sms-amount="${idx}" inputmode="decimal" type="number" min="0" step="0.01" value="${p.amount||''}"></div></div><div class="field-grid"><div class="field"><label>التصنيف</label><select data-sms-cat="${idx}">${options([...new Set([...categories(),'إيداع','راتب','تحويل وارد'])],p.category)}</select></div><div class="field"><label>التاريخ</label><input data-sms-date="${idx}" type="date" value="${p.date}"></div></div><div class="field"><label>اسم المكان أو وصف المعاملة</label><input data-sms-note="${idx}" maxlength="140" value="${esc(p.merchant||'')}" placeholder="المحل أو الجهة المكتوبة في الرسالة"></div><div class="checks"><input type="checkbox" data-sms-exclude="${idx}" id="exs${idx}"><label for="exs${idx}">تحويل بين حساباتي (استبعاد)</label></div></div>`).join('')}</div><button class="btn block" id="saveSms" style="margin-top:15px">حفظ الرسائل المؤكدة</button><p class="footnote">لو التحليل مش متأكد من نوع أو مبلغ عملية، اخترهم يدويًا أو تجاهل الرسالة.</p></div>`;$('#saveSms').addEventListener('click',async()=>{let added=0,duplicates=0,ignored=0,unresolved=0;for(let k=0;k<smsPreview.length;k++){const p=smsPreview[k],type=$(`[data-sms-type="${k}"]`).value,amount=cleanMoney($(`[data-sms-amount="${k}"]`).value),category=$(`[data-sms-cat="${k}"]`).value,note=$(`[data-sms-note="${k}"]`).value.trim().slice(0,140),date=$(`[data-sms-date="${k}"]`).value,excluded=$(`[data-sms-exclude="${k}"]`).checked;if(type==='ignore'||p.ignored){ignored++;continue}if(!type||!amount||!validDate(date)){unresolved++;continue}const fp=checksum(date+'|'+p.sender.toLowerCase()+'|'+p.body.replace(/\s+/g,' ').toLowerCase());if(state.transactions.some(t=>t.fingerprint===fp)){duplicates++;continue}state.transactions.push({id:uuid(),date,amount,type,category:category|| (type==='deposit'?'إيداع':'أخرى'),source:p.source||'SMS',sender:p.sender,note:note||(type==='deposit'?'إيداع':'عملية سحب')+(p.sender?' - '+p.sender:''),originalMessage:p.body,fingerprint:fp,excluded,createdAt:new Date().toISOString()});added++}if(added&&!await persist())return;closeModal();render();toast(`تم تسجيل ${added} عملية، وتجاهل ${duplicates} مكررة و${ignored} مستبعدة${unresolved?'، و'+unresolved+' تحتاج مراجعة':''}`)})}
function openInstallmentForm(id){const i=id?state.installments.find(x=>x.id===id):null;openModal(i?'تعديل القسط':'إضافة قسط جديد',`<form id="installForm"><div class="field"><label>اسم القسط *</label><input name="name" required maxlength="100" value="${esc(i?.name||'')}" placeholder="مثلاً: قسط الموبايل"></div><div class="field-grid"><div class="field"><label>القيمة الشهرية *</label><input type="number" min="0.01" max="999999999999" step="0.01" name="amount" required inputmode="decimal" value="${i?.amount??''}"></div><div class="field"><label>يوم الدفع *</label><select name="dueDay">${Array.from({length:31},(_,j)=>`<option value="${j+1}" ${+i?.dueDay===j+1?'selected':''}>يوم ${j+1}</option>`).join('')}</select></div></div><div class="field-grid"><div class="field"><label>بداية القسط</label><input name="startMonth" type="month" required value="${esc(i?.startMonth||viewMonth)}"></div><div class="field"><label>عدد الأشهر (0 = مستمر)</label><input type="number" min="0" max="240" step="1" name="count" value="${i?.count??0}"></div></div><p class="field-hint">لو اخترت يوم 31 في شهر أقصر، هيكون الاستحقاق آخر يوم في الشهر. القسط مش هيتخصم تلقائيًا غير بعد تسجيل الدفع.</p><button class="btn block" type="submit">${i?'حفظ تعديل القسط':'إضافة القسط'}</button>${i?'<button class="btn danger block" type="button" id="deleteInstall" style="margin-top:9px">حذف القسط</button>':''}</form>`,()=>{$('#installForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')).trim(),amount=cleanMoney(f.get('amount')),dueDay=+f.get('dueDay'),startMonth=String(f.get('startMonth')),count=+f.get('count');if(!name||!amount||dueDay<1||dueDay>31||!/^(20\d\d|19\d\d)-\d\d$/.test(startMonth)||count<0){toast('راجع بيانات القسط');return}const newItem={id:i?.id||uuid(),name,amount,dueDay,startMonth,count,active:true,payments:i?.payments||[]};if(i)Object.assign(i,newItem);else state.installments.push(newItem);if(!await persist())return;closeModal();render();toast('تم حفظ القسط')});$('#deleteInstall')?.addEventListener('click',async()=>{if(!confirm('تحذف القسط؟ معاملات الدفع المسجلة تفضل في المصروفات؛ الحذف لن يمسحها.'))return;state.installments=state.installments.filter(x=>x.id!==i.id);await persist();closeModal();render();toast('تم حذف القسط مع الاحتفاظ بالمعاملات')})})}
function openPayment(id){const i=state.installments.find(x=>x.id===id);if(!i)return;const existing=paymentFor(i,viewMonth);if(existing)return toast('القسط مدفوع بالفعل في الشهر ده');const matching=state.transactions.filter(t=>t.date?.startsWith(viewMonth)&&t.type==='withdrawal'&&!t.excluded&&!t.linkedInstallment&&Math.abs(t.amount-i.amount)<.011);openModal('تسجيل دفع القسط',`<p class="small muted">${esc(i.name)} — ${money(i.amount)} ج.م — ${monthName(viewMonth)}</p><div class="field"><label>طريقة التسجيل</label><select id="paymentSource"><option value="new">إنشاء عملية سحب جديدة بالقيمة نفسها</option>${matching.map(t=>`<option value="${esc(t.id)}">ربط بسحب موجود: ${esc(t.note||t.source)} (${displayDate(t.date)})</option>`).join('')}</select></div><p class="footnote">لو كانت رسالة البنك اتسجلت بالفعل، اختار العملية الموجودة بدل إنشاء سحب جديد عشان المبلغ ما يتحسبش مرتين.</p><button class="btn block" id="confirmPay">✓ تأكيد دفع القسط</button>`,()=>{$('#confirmPay').addEventListener('click',async()=>{if(paymentFor(i,viewMonth))return toast('مسجل مدفوع بالفعل');let txId=null,method=$('#paymentSource').value;let payDate=viewMonth===monthKey()?localDate():nextDueDate(i,viewMonth);if(method==='new'){txId=uuid();state.transactions.push({id:txId,date:payDate,amount:i.amount,type:'withdrawal',category:'أقساط',source:'قسط شهري',note:`قسط ${i.name}`,originalMessage:'',receiptDataUrl:'',linkedInstallment:i.id,installmentCreated:true,createdAt:new Date().toISOString()})}else {let t=state.transactions.find(x=>x.id===method);if(!t)return toast('المعاملة غير موجودة');t.linkedInstallment=i.id;txId=t.id;payDate=t.date}i.payments.push({month:viewMonth,txId,date:payDate});if(!await persist())return;closeModal();render();toast('تم تسجيل القسط مدفوعًا بدون تكرار السحب')})})}
function installmentDetails(id){const i=state.installments.find(x=>x.id===id);if(!i)return;let p=paymentFor(i,viewMonth),completed=(i.payments||[]).length,remaining=i.count?Math.max(0,(i.count-completed)*i.amount):null;openModal('تفاصيل القسط',`<h3>${esc(i.name)}</h3><div class="metric"><span class="muted small">قيمة القسط الشهري</span><strong>${money(i.amount)} ج.م</strong></div><div class="metric"><span class="muted small">يوم الدفع</span><strong>${i.dueDay} من كل شهر</strong></div><div class="metric"><span class="muted small">بداية الأقساط</span><strong>${monthName(i.startMonth)}</strong></div><div class="metric"><span class="muted small">الأقساط المدفوعة</span><strong>${completed}${i.count?' / '+i.count:''}</strong></div><div class="metric"><span class="muted small">المتبقي من إجمالي الأقساط</span><strong>${remaining===null?'غير محدد':money(remaining)+' ج.م'}</strong></div>${p?`<div class="alert good">مدفوع عن شهر ${monthName(viewMonth)} يوم ${displayDate(p.date)}</div><button class="btn secondary block" id="undoPayment" style="margin-top:12px">إلغاء تسجيل الدفع لهذا الشهر</button>`:''}<div class="buttons" style="margin-top:16px"><button class="btn secondary block" id="editInstallDetail">تعديل بيانات القسط</button></div>`,()=>{$('#editInstallDetail').addEventListener('click',()=>openInstallmentForm(i.id));$('#undoPayment')?.addEventListener('click',async()=>{if(!confirm('إلغاء حالة الدفع؟ لو التطبيق أنشأ عملية السحب، هتتحذف. أما لو ربطنا برسالة موجودة، هتفضل المعاملة محفوظة.'))return;i.payments=i.payments.filter(x=>x.month!==viewMonth);const t=state.transactions.find(x=>x.id===p.txId);if(t?.installmentCreated)state.transactions=state.transactions.filter(x=>x.id!==t.id);else if(t)t.linkedInstallment='';await persist();closeModal();render();toast('تم إلغاء حالة الدفع')})})}
function addMonths(month,count){return shiftMonth(month,count)}
function calendarDate(date){return date.replace(/-/g,'')}
function icsEsc(s){return String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function exportCalendar(){if(!state.installments.length)return toast('أضف قسط واحد على الأقل الأول');let events=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Hesabaty//Installments v1//AR','CALSCALE:GREGORIAN','METHOD:PUBLISH','X-WR-CALNAME:أقساط حساباتي'];let limit=0;for(const i of state.installments){const count=i.count?Math.min(+i.count,120):36;for(let step=0;step<count;step++){const m=addMonths(i.startMonth||monthKey(),step),due=nextDueDate(i,m);if(due<shiftMonth(monthKey(),-1)+'-01')continue;const stamp=calendarDate(due);const dt=new Date();const created=`${dt.getUTCFullYear()}${pad(dt.getUTCMonth()+1)}${pad(dt.getUTCDate())}T${pad(dt.getUTCHours())}${pad(dt.getUTCMinutes())}${pad(dt.getUTCSeconds())}Z`;events.push('BEGIN:VEVENT',`UID:${icsEsc(i.id)}-${m}@hesabaty-local`,`DTSTAMP:${created}`,`DTSTART:${stamp}T090000`,`DTEND:${stamp}T091500`,`SUMMARY:${icsEsc('قسط '+i.name+' - '+money(i.amount)+' جنيه')}`,`DESCRIPTION:${icsEsc('تذكير بقسط شهري من تطبيق حساباتي. تسجيل الدفع يتم يدويًا داخل التطبيق.')}`,'BEGIN:VALARM','ACTION:DISPLAY',`DESCRIPTION:${icsEsc('بكرة معاد قسط '+i.name+' بقيمة '+money(i.amount)+' جنيه')}`,'TRIGGER:-P1D','END:VALARM','END:VEVENT');limit++;if(limit>=500)break}if(limit>=500)break}events.push('END:VCALENDAR');downloadBlob(new Blob([events.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),'hesabaty-installments.ics');toast(`تم تجهيز ${limit} موعد للتقويم. افتح الملف وأضف المواعيد إلى Calendar.`)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},2000)}
function exportBackup(){const archive={format:'hesabaty-backup',appVersion:VERSION,exportedAt:new Date().toISOString(),data:state};downloadBlob(new Blob([JSON.stringify(archive,null,2)],{type:'application/json;charset=utf-8'}),'hesabaty-backup-'+localDate()+'.json');toast('تم تجهيز نسخة احتياطية؛ احتفظ بيها في Files أو iCloud Drive')}
async function importBackup(file){if(!file)return;if(file.size>35*1024*1024)return toast('ملف النسخة الاحتياطية أكبر من المسموح');try{const parsed=JSON.parse(await file.text());if(parsed.format!=='hesabaty-backup'||!parsed.data)throw Error('ملف مش نسخة احتياطية من حساباتي');if(parsed.data.schemaVersion>SCHEMA)throw Error('النسخة من إصدار أحدث؛ حدث التطبيق أولًا');const imported=normalizeState(parsed.data);if(!confirm(`هتستبدل البيانات الحالية (${state.transactions.length} عملية) بالنسخة دي (${imported.transactions.length} عملية). خُد نسخة احتياطية من بياناتك الحالية الأول. هل تؤكد؟`))return;const prior=state;state=imported;if(!await persist()){state=prior;return}viewMonth=monthKey();render();toast('تم استرجاع الحسابات والأقساط بنجاح')}catch(err){console.error(err);toast(err.message||'تعذر قراءة النسخة الاحتياطية')}}
function shortcutGuide(){openModal('صيغة استيراد رسائل Shortcuts',`<p class="footnote">الأبلكيشن الحالي يستورد ملف رسائل، لكنه لا يقرأ Messages مباشرة. تقدر تعمل Automation في تطبيق Shortcuts يعتمد على استقبال Message، ويحفظ نص الرسالة ومرسلها وتاريخها في ملف محلي. طريقة مشاركة الملف بين Shortcuts والتطبيق بتختلف حسب نوع التثبيت.</p><strong>مثال ملف JSON:</strong><div class="receipt" style="margin:12px 0;direction:ltr;text-align:left;font-size:12px">[<br>&nbsp;{<br>&nbsp;&nbsp;"sender":"CIB",<br>&nbsp;&nbsp;"date":"2026-10-16",<br>&nbsp;&nbsp;"body":"Purchase of EGP 850 at Carrefour"<br>&nbsp;}<br>]</div><strong>أو ملف CSV:</strong><div class="receipt" style="margin:12px 0;direction:ltr;text-align:left;font-size:12px">sender,date,body<br>CIB,2026-10-16,"Purchase of EGP 850 at Carrefour"</div><p class="footnote">مهم: لازم يكون الملف بدون رسائل أكواد OTP، وراجع المبالغ قبل الحفظ. ما تديش أي اختصار مجهول صلاحية الوصول لرسائلك.</p><button class="btn secondary block" id="closeGuide">فهمت</button>`,()=>{$('#closeGuide').addEventListener('click',closeModal)})}
function addDemo(){if(!confirm('إضافة معاملات تجريبية في الشهر الحالي لاختبار التطبيق؟ تقدر تحذفها بعد كده.'))return;const demo=[['deposit',100000,'إيداع','راتب','راتب شهري'],['withdrawal',8500,'مستلزمات بيت','CIB','مشتريات السوبر ماركت'],['withdrawal',7500,'مصاريف شخصية','CIB','مصاريف شخصية'],['withdrawal',4000,'اشتراكات','CIB','اشتراكات وخدمات']];for(const [type,amount,category,source,note] of demo)state.transactions.push({id:uuid(),type,amount,category,source,note,date:localDate(),originalMessage:'',createdAt:new Date().toISOString()});state.installments.push({id:uuid(),name:'قسط موبايل (تجريبي)',amount:2000,dueDay:25,startMonth:monthKey(),count:12,active:true,payments:[]});persist().then(ok=>{if(ok){page='home';viewMonth=monthKey();render();toast('اتضافت بيانات تجريبية: إجمالي 100,000 وسحب 20,000')}})}
async function clearAll(){if(!confirm('هل متأكد إنك عايز تمسح كل الحسابات والأقساط نهائيًا؟ اعمل نسخة احتياطية الأول.'))return;const phrase=prompt('لتأكيد الحذف اكتب كلمة: مسح');if(phrase!=='مسح'){toast('تم إلغاء الحذف');return}const prior=state;state=initialState();if(!await persist()){state=prior;return}viewMonth=monthKey();page='home';render();toast('اتمسحت كل البيانات من التطبيق')}
function navigate(to,filter=null){page=to;if(filter)typeFilter=filter;render();window.scrollTo({top:0,behavior:'instant'})}
function attachEvents(){document.addEventListener('click',async e=>{let t=e.target.closest('button,[data-page-link],[data-detail],[data-pay],[data-edit-install],[data-detail-install]');if(!t)return;
if(t.dataset.page){navigate(t.dataset.page);return}
if(t.id==='topSettings'){navigate('settings');return}
if(t.id==='fab'){openTransactionForm();return}
if(t.dataset.pageLink){navigate(t.dataset.pageLink,t.dataset.filter||null);return}
if(t.dataset.monthChange){viewMonth=shiftMonth(viewMonth,+t.dataset.monthChange);render();return}
if(t.dataset.type){typeFilter=t.dataset.type;render();return}
if(t.dataset.detail){openDetails(t.dataset.detail);return}
if(t.dataset.pay){openPayment(t.dataset.pay);return}
if(t.dataset.editInstall){openInstallmentForm(t.dataset.editInstall);return}
if(t.dataset.detailInstall){installmentDetails(t.dataset.detailInstall);return}
switch(t.dataset.action){case'transaction-new':openTransactionForm();break;case'sms-open':openSmsModal();break;case'installment-new':openInstallmentForm();break;case'export-calendar':exportCalendar();break;case'report-pdf':window.hesabatyReport?.exportMonth(viewMonth,state.transactions);break;case'backup-export':exportBackup();break;case'pdf-export':exportMonthlyPdf();break;case'backup-import':$('#hiddenImport').value='';$('#hiddenImport').click();break;case'shortcut-guide':shortcutGuide();break;case'demo':addDemo();break;case'clear-all':clearAll();break;default:break}});
document.addEventListener('input',e=>{if(e.target.id==='txnSearch'){searchText=e.target.value;const cursor=e.target.selectionStart;let arr=state.transactions.filter(t=>t.date?.slice(0,7)===viewMonth&&(typeFilter==='all'||t.type===typeFilter));if(searchText){let q=searchText.toLowerCase();arr=arr.filter(t=>[t.note,t.category,t.source,t.sender,t.originalMessage].some(x=>String(x||'').toLowerCase().includes(q)))}arr.sort((a,b)=>(b.date||'').localeCompare(a.date||''));$('#txnList').innerHTML=arr.length?arr.map(transactionRow).join(''):empty('لا توجد معاملات مطابقة','🔎')}});
$('#hiddenImport').addEventListener('change',e=>importBackup(e.target.files[0]));$('#hiddenSmsFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024)return toast('حجم ملف الرسائل كبير جدًا (الحد 3 ميجابايت)');try{const records=readMessageData(await f.text(),f.name);if(!records.length)throw Error('لا توجد رسائل داخل الملف');if(!$('#smsResults'))openSmsModal();showSmsPreview(records);toast(`تم قراءة ${Math.min(records.length,200)} رسالة للمراجعة`)}catch(err){toast(err.message||'تعذر قراءة ملف الرسائل')}})}
async function boot(){attachEvents();await initStore();render();if('serviceWorker'in navigator&&location.protocol.startsWith('http')){try{await navigator.serviceWorker.register('./sw.js')}catch(e){console.info('Service worker not available',e)}}}
boot().catch(e=>{console.error(e);$('#main').innerHTML='<div class="alert">حصل خطأ أثناء فتح التطبيق. جرّب تحديث الصفحة، واحتفظ بنسخة من بيانات المتصفح قبل أي مسح.</div>'});
